return {["被动招式"]={["AzoicHook1"]={["actionText"]=[[$N步法轻盈，绕$n身周飞转，手中$Nw如电，只见得几道寒光，$N已相$n胸腹连连横削而出。]],["atkList"]=[[AzoicHook1P1]],["attack"]=25.29,["attackAverage"]=30.35,["damageType"]=[[震伤#1]],["hit"]=0.8,["hurtPosClass"]=[[default]],["id"]=[[AzoicHook1]],["lv"]=0,["skillId"]=[[AzoicHook]],["tiliCost"]=50,["topLimit"]=80,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[诛求无已]]},["AzoicHook10"]={["actionText"]=[[$N使出一招「阎王柬帖」，真气聚与碗上，只平平地将$Nw挥出，却包含着摧枯拉朽的剑气，横扫向$n。]],["atkList"]=[[AzoicHook10P1]],["attack"]=41.82,["attackAverage"]=37.83,["damageType"]=[[震伤#8]],["hit"]=0.8,["hurtPosClass"]=[[default]],["id"]=[[AzoicHook10]],["lv"]=550,["skillId"]=[[AzoicHook]],["tiliCost"]=50,["topLimit"]=160,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[阎王柬帖]]},["AzoicHook2"]={["actionText"]=[[$N使出一式「十死无生」，身影一闪，已至$n身后，手中$Nw猛然一刺，直取$n后心。]],["atkList"]=[[AzoicHook2P1]],["attack"]=25.9,["attackAverage"]=30.71,["damageType"]=[[震伤#1]],["hit"]=0.8,["hurtPosClass"]=[[default]],["id"]=[[AzoicHook2]],["lv"]=100,["skillId"]=[[AzoicHook]],["tiliCost"]=50,["topLimit"]=83,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[十死无生]]},["AzoicHook3"]={["actionText"]=[[$N将一把钩掷向$n，随后身影一闪消失在原地，$n只觉得后背一凉，$N出现在其身后，手中$Nw向$n的要害砍去。]],["atkList"]=[[AzoicHook3P1]],["attack"]=26.71,["attackAverage"]=31.16,["damageType"]=[[震伤#1]],["hit"]=0.8,["hurtPosClass"]=[[default]],["id"]=[[AzoicHook3]],["lv"]=150,["skillId"]=[[AzoicHook]],["tiliCost"]=50,["topLimit"]=87,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[命如草木]]},["AzoicHook4"]={["actionText"]=[[$N前跨一步，手中$Nw向前横削而去，剑气凛冽，如朔风过境，直直地劈向$n。]],["atkList"]=[[AzoicHook4P1]],["attack"]=27.72,["attackAverage"]=31.69,["damageType"]=[[震伤#2]],["hit"]=0.8,["hurtPosClass"]=[[default]],["id"]=[[AzoicHook4]],["lv"]=200,["skillId"]=[[AzoicHook]],["tiliCost"]=50,["topLimit"]=92,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[刮野扫地]]},["AzoicHook5"]={["actionText"]=[[$N单脚重踏地面，猛地蹿至$n身前，使一式「身魂俱朽」，手中$Nw一把直取$n面门，一把直取$n心口。]],["atkList"]=[[AzoicHook5P1]],["attack"]=29.15,["attackAve