uan7P1]],["attack"]=7.21,["attackAverage"]=4.32,["damageType"]=[[瘀伤#6]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[baihuacuoquan7]],["lv"]=80,["skillId"]=[[baihuacuoquan]],["tiliCost"]=50,["topLimit"]=5,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[游空探爪]]},["baihuacuoquan8"]={["actionText"]=[[只见$N拉开架式，双手将武当派的绵掌使得密不透风，招招不离$n的$l。]],["atkList"]=[[baihuacuoquan8P1]],["attack"]=8.44,["attackAverage"]=5.05,["damageType"]=[[瘀伤#6]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[baihuacuoquan8]],["lv"]=100,["skillId"]=[[baihuacuoquan]],["tiliCost"]=50,["topLimit"]=15,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[小绵掌]]},["baihuacuoquan9"]={["actionText"]=[[$N突然飞身一跃而起，双手握做爪状，朝着$n的$l猛然抓去，凛然是鹰爪功的招式。]],["atkList"]=[[baihuacuoquan9P1]],["attack"]=9.66,["attackAverage"]=5.78,["damageType"]=[[瘀伤#7]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[baihuacuoquan9]],["lv"]=120,["skillId"]=[[baihuacuoquan]],["tiliCost"]=50,["topLimit"]=20,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[鹰爪]]},["baimangbianfa1"]={["actionText"]=[[$N以内力灌注鞭身，蓦然一挥，手中$Nw宛若腾蛇张牙舞爪。$n只觉得全身俱在$Nw笼罩之下。竟是一招「白蟒缠身」！]],["atkList"]=[[baimangbianfa1P1]],["attack"]=7.79,["attackAverage"]=9.35,["damageType"]=[[瘀伤#1]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa1]],["lv"]=0,["skillId"]=[[baimangbianfa]],["tiliCost"]=53,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[白蟒缠身]]},["baimangbianfa2"]={["actionText"]=[[$N连抖手腕，$Nw扭曲蜿蜒，如一条伏地灵蛇，直取$n双足。正是一招「画蟒添足」。]],["atkList"]=[[baimangbianfa2P1]],["attack"]=8.93,["attackAverage"]=10.03,["damageType"]=[[瘀伤#3]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa2]],["lv"]=100,["skillId"]=[[baimangbianfa]],["tiliCost"]=53,["topLimit"]=1,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[画蟒添足]]},["baimangbianfa3"]={["actionText"]=[[$N单手持鞭，一式「白蟒脱鳞」使来，只见$Nw在地面来回扫过，将砂石枯叶卷上高空，鞭尾直取$n下盘！]],["atkList"]=[[baimangbianfa3P1]],["attack"]=10.65,["attackAverage"]=10.95,["damageType"]=[[瘀伤#4]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa3]],["lv"]=150,["skillId"]=[[baimangbianfa]],["tiliCost"]=53,["topLimit"]=2,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[白蟒脱鳞]]},["baimangbianfa4"]={["actionText"]=[[$N力贯鞭梢，一招「蛇牙噬身」，手中$Nw舞出满天鞭影，有虚有实。鞭尾好似道道蛇牙，要让$n的身体皮开肉绽。]],["atkList"]=[[baimangbianfa4P1]],["attack"]=13.13,["attackAverage"]=12.15,["damageType"]=[[瘀伤#5]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa4]],["lv"]=200,["skillId"]=[[baimangbianfa]],["tiliCost"]=53,["topLimit"]=4,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[蛇牙噬身]]},["baimangbianfa5"]={["actionText"]=[[$N低身向前，甩出一招「盘蛇踞地」，$Nw卷得如同暴风螺旋，鞭影重重蓄力凝成一击，席卷起$n往外掀砸。]],["atkList"]=[[baimangbianfa5P1]],["attack"]=15.99,["attackAverage"]=13.56,["damageType"]=[[瘀伤#6]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa5]],["lv"]=250,["skillId"]=[[baimangbianfa]],["tiliCost"]=53,["topLimit"]=6,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[盘蛇踞地]]},["baimangbianfa6"]={["actionText"]=[[$N运力灌于鞭内，劈头一挥，一招「巨蟒劈尾」兜头罩向$n。$Nw于半空炸响连连，其中威力令人不寒而栗。]],["atkList"]=[[baimangbianfa6P1]],["attack"]=19.62,["attackAverage"]=15.22,["damageType"]=[[瘀伤#7]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa6]],["lv"]=300,["skillId"]=[[baimangbianfa]],["tiliCost"]=53,["topLimit"]=8,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[巨蟒劈尾]]},["baimangbianfa7"]={["actionText"]=[[$N挥鞭急转，手中$Nw横卷而出，急急绞向$n脖颈。竟是一招「蛇身绞首」！]],["atkList"]=[[baimangbianfa7P1]],["attack"]=24.21,["attackAverage"]=17.2,["damageType"]=[[瘀伤#8]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa7]],["lv"]=400,["skillId"]=[[baimangbianfa]],["tiliCost"]=53,["topLimit"]=11,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[蛇身绞首]]},["baimangbianfa8"]={["actionText"]=[[只见$N朗声大笑，高高跳起，把$Nw抖得笔直，一招「笑斩白蛇」兜头打来，摧枯拉朽般击向$n的面门。]],["atkList"]=[[baimangbianfa8P1]],["attack"]=29.58,["attackAverage"]=19.49,["damageType"]=[[瘀伤#9]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[baimangbianfa8]],["lv"]=450,["skillId"]=[[baimangbianfa]],["tili