iyuantongbeiquan4"]={["actionText"]=[[$N猱身而上，双拳直出，锁向$n颈部。]],["atkList"]=[[baiyuantongbeiquan4P1]],["attack"]=6.78,["attackAverage"]=4.85,["damageType"]=[[砸伤#1]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[baiyuantongbeiquan4]],["lv"]=80,["skillId"]=[[baiyuantongbeiquan]],["tiliCost"]=43,["topLimit"]=30,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[白猿抱月]]},["baiyuantongbeiquan5"]={["actionText"]=[[只见$N身形暴涨，右拳猛地击向$n，左手还捏着一个剑诀，随时准备激发！这是白猿通背拳中的招式HIB「白猿练剑」NOR！]],["atkList"]=[[baiyuantongbeiquan5P1]],["attack"]=9.52,["attackAverage"]=6.17,["damageType"]=[[砸伤#1]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[baiyuantongbeiquan5]],["lv"]=120,["skillId"]=[[baiyuantongbeiquan]],["tiliCost"]=43,["topLimit"]=50,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[白猿练剑]]},["baiyuantongbeiquan6"]={["actionText"]=[[$N飞身上前，距$n两丈之时，身形下沉，右拳上击，打向$n下颌。]],["atkList"]=[[baiyuantongbeiquan6P1]],["attack"]=12.26,["attackAverage"]=7.59,["damageType"]=[[砸伤#1]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[baiyuantongbeiquan6]],["lv"]=150,["skillId"]=[[baiyuantongbeiquan]],["tiliCost"]=43,["topLimit"]=100,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[白猿抄水]]},["baiyuantongbeiquan7"]={["actionText"]=[[$N双拳交于胸前，然后一前一后地快速击出，这是白猿通背拳中的著名杀招HIR「白猿献果」NOR!这一击，如同一个春秋时的刺客，带着死士的决然杀向$n！]],["atkList"]=[[baiyuantongbeiquan7P1]],["attack"]=20.78,["attackAverage"]=10.07,["damageType"]=[[砸伤#1]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[baiyuantongbeiquan7]],["lv"]=200,["skillId"]=[[baiyuantongbeiquan]],["tiliCost"]=43,["topLimit"]=200,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[白猿献果]]},["baiyuantongbeiquan8"]={["actionText"]=[[$N飞扑上前，左拳打向$n胸口，一手成爪，抓向$n胯部。]],["atkList"]=[[baiyuantongbeiquan8P1]],["attack"]=28.94,["attackAverage"]=13.15,["damageType"]=[[砸伤#1]],["hit"]=0.3,["hurtPosClass"]=[[default]],["id"]=[[baiyuantongbeiquan8]],["lv"]=300,["skillId"]=[[baiyuantongbeiquan]],["tiliCost"]=43,["topLimit"]=200,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[白猿摘桃]]},["bajidaqi