["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[乌龙入洞]]},["bajiquan5"]={["actionText"]=[[$N摆出一个拳架，左手虚挥，右手前探索，一招「猿猴夺食」打向$n的要害之处。]],["atkList"]=[[bajiquan5P1]],["attack"]=10.82,["attackAverage"]=5.52,["damageType"]=[[瘀伤#5]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[bajiquan5]],["lv"]=80,["skillId"]=[[bajiquan]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[猿猴夺食]]},["bajiquan6"]={["actionText"]=[[$N稳住下盘，双拳紧握，使一招「灵犬角斗」将$n的进攻化解于无形，又打得$n左支右绌，疲于防守。]],["atkList"]=[[bajiquan6P1]],["attack"]=15.63,["attackAverage"]=7.73,["damageType"]=[[瘀伤#6]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[bajiquan6]],["lv"]=100,["skillId"]=[[bajiquan]],["tiliCost"]=47,["topLimit"]=140,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[灵犬角斗]]},["bajiquan7"]={["actionText"]=[[$N突然迈步挺身，大开大合，一招「饥鹰捉兔」劈头盖脑地向$n打去，$n周身要害没有一处不是打击的目标，没有一处不门户洞开！]],["atkList"]=[[bajiquan7P1]],["attack"]=21.34,["attackAverage"]=10.28,["damageType"]=[[瘀伤#7]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[bajiquan7]],["lv"]=150,["skillId"]=[[bajiquan]],["tiliCost"]=47,["topLimit"]=180,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[饥鹰捉兔]]},["bajiquan8"]={["actionText"]=[[$N一个跨步，使出八极拳的杀招「猛虎硬爬山」，整个人似乎化作无坚不摧的利器，全身上下每个部位皆可伤人，这一招不惮以伤换伤、置之死地而后生，令观者热血沸腾。]],["atkList"]=[[bajiquan8P1]],["attack"]=27.98,["attackAverage"]=13.19,["damageType"]=[[瘀伤#8]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[bajiquan8]],["lv"]=200,["skillId"]=[[bajiquan]],["tiliCost"]=47,["topLimit"]=220,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[猛虎硬爬山]]},["bajiquan9"]={["actionText"]=[[$N一个跨步，使出杀招「猛虎搏兔」，劲力刚猛，挟猛虎之势，向$n猛扑而去。]],["atkList"]=[[bajiquan9P1]],["attack"]=35.77,["attackAverage"]=16.5,["damageType"]=[[瘀伤#9]],["hit"]=0.1,["hurtPosClass"]=[[default]],["id"]=[[bajiquan9]],["lv"]=250,["skillId"]=[[bajiquan]],["tiliCost"]=47,["topLimit"]=280,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[猛虎搏兔]]},["baniaochaofengqiang1"]={["actionText"]=[[$N使一招「飞燕啄泥」，手中$Nw连续刺向$n面门和哽嗓。]],["atkList"]=[[bani