]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi1]],["lv"]=0,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[晓天初阳]]},["duanshiyiyangzhi10"]={["actionText"]=[[$N面带微笑，伸出右食指，缓缓点向$n胸口，这招RAN「暮云映日」NOR劲气弥漫，却无丝毫破空之声。]],["atkList"]=[[duanshiyiyangzhi10P1]],["attack"]=13.34,["attackAverage"]=9.42,["damageType"]=[[内伤#7]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi10]],["lv"]=180,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=35,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[暮云映日]]},["duanshiyiyangzhi11"]={["actionText"]=[[只见$N食指微屈，一指RAN「九天乾阳」NOR点出，气象森严，雍容肃穆，于威猛之中不脱王者风度！]],["atkList"]=[[duanshiyiyangzhi11P1]],["attack"]=14.62,["attackAverage"]=10.16,["damageType"]=[[震伤#8]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi11]],["lv"]=200,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=50,["zhaoId"]=11,["zhaoIdText"]=[[第十一招]],["zhaoName"]=[[九天乾阳]]},["duanshiyiyangzhi12"]={["actionText"]=[[HIW$N头顶白气氤氲，渐聚渐浓，便似蒸笼一般，食指伸出，一式RAN「三阳开泰」NOR按向$n！]],["atkList"]=[[duanshiyiyangzhi12P1]],["attack"]=15.97,["attackAverage"]=10.91,["damageType"]=[[震伤#8]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi12]],["lv"]=250,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=80,["zhaoId"]=12,["zhaoIdText"]=[[第十二招]],["zhaoName"]=[[三阳开泰]]},["duanshiyiyangzhi2"]={["actionText"]=[[$N一指RAN「日出霞光」NOR，激出的一股罡气涌向$n，看似是温淳平和，但沛然浑厚，无可与抗。]],["atkList"]=[[duanshiyiyangzhi2P1]],["attack"]=3.6,["attackAverage"]=3.6,["damageType"]=[[内伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi2]],["lv"]=20,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=0,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[日出霞光]]},["duanshiyiyangzhi3"]={["actionText"]=[[忽听嗤嗤轻响，一股柔和的气流自$N手指涌出，正是一招RAN「阳春暖融」NOR，缓缓点向$n$l。]],["atkList"]=[[duanshiyiyangzhi3P1]],["attack"]=4.8,["attackAverage"]=4.32,["damageType"]=[[刺伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi3]],["lv"]=40,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=0,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[阳春暖融]]},["duanshiyiyangzhi4"]={["actionText"]=[[$N一步跨到$n身后，又如闪电般跃回，一式「鲁阳返日」，右手食指疾出，指向$n的$l。]],["atkList"]=[[duanshiyiyangzhi4P1]],["attack"]=6.01,["attackAverage"]=5.04,["damageType"]=[[刺伤#2]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi4]],["lv"]=60,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=5,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[鲁阳返日]]},["duanshiyiyangzhi5"]={["actionText"]=[[$N左手轻扬，右手食指挟着雄浑内力疾点$n的$l，招式光明坦荡，正是一式「阳春白雪」。]],["atkList"]=[[duanshiyiyangzhi5P1]],["attack"]=7.22,["attackAverage"]=5.77,["damageType"]=[[刺伤#3]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi5]],["lv"]=80,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=10,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[阳春白雪]]},["duanshiyiyangzhi6"]={["actionText"]=[[$N身影飘起，一式「阳钩挥天」，身形自上而下闪出，右手猛然劲点向$n的$l。]],["atkList"]=[[duanshiyiyangzhi6P1]],["attack"]=8.45,["attackAverage"]=6.5,["damageType"]=[[刺伤#4]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi6]],["lv"]=100,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=20,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[阳钩挥天]]},["duanshiyiyangzhi7"]={["actionText"]=[[$N踏前一步，伸指凌空轻轻一点，$n只觉气息一紧，已被RAN「赤日焦阳」NOR的刚阳气劲触到$l。]],["atkList"]=[[duanshiyiyangzhi7P1]],["attack"]=9.66,["attackAverage"]=7.22,["damageType"]=[[内伤#5]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi7]],["lv"]=120,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=20,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[赤日焦阳]]},["duanshiyiyangzhi8"]={["actionText"]=[[$N衣袖轻摆，罡阳柔气从袖底挥出，涌向$n的$l，正是玄功若神的一招RAN「晓阳云暖」NOR。]],["atkList"]=[[duanshiyiyangzhi8P1]],["attack"]=10.88,["attackAverage"]=7.95,["damageType"]=[[刺伤#6]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi8]],["lv"]=140,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=25,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[晓阳云暖]]},["duanshiyiyangzhi9"]={["actionText"]=[[$N左掌斜削，突然间变掌为指，嗤的一式「如日方升」，使出一阳指力，疾点$n的$l。]],["atkList"]=[[duanshiyiyangzhi9P1]],["attack"]=12.11,["attackAverage"]=8.68,["damageType"]=[[刺伤#6]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[duanshiyiyangzhi9]],["lv"]=160,["skillId"]=[[duanshiyiyangzhi]],["tiliCost"]=52,["topLimit"]=30,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[如日方升]]},["duanyunfu1"]={["actionText"]=[[$N蓦地腾空跃起，双手紧握$Nw，对准$n的头顶，自上而下地砍了下去，只在半空中留下一团巨大的黑影。]],["atkList"]=[[duanyunfu1P1]],["attack"]=4,["attackAverage"]=4.8,["damageType"]=[[砍伤#1]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu1]],["lv"]=0,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[乌云压顶]]},["duanyunfu2"]={["actionText"]=[[$N突然发一声喊，冲前两步，手中$Nw由下而上反撩$n下三路，$n见到一道淡黄色的气影逼向自己，情知不妙，急忙招架。]],["atkList"]=[[duanyunfu2P1]],["attack"]=6,["attackAverage"]=6,["damageType"]=[[砍伤#2]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu2]],["lv"]=10,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=0,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[斧断三川]]},["duanyunfu3"]={["actionText"]=[[$N忽然虎吼一声，闪身斜向左前方冲出一步，身体微晃，手中$Nw在空中划出一道淡影，急速横扫$n的右肩，气势迫人。]],["atkList"]=[[duanyunfu3P1]],["attack"]=8,["attackAverage"]=7.2,["damageType"]=[[砍伤#3]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu3]],["lv"]=20,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=0,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[暗影横扫]]},["duanyunfu4"]={["actionText"]=[[$N突然抽身向右滚倒，随即跳起，就在跳起的一瞬间，已单臂握着$Nw砸向$n的左肋，出手既快且狠。]],["atkList"]=[[duanyunfu4P1]],["attack"]=10,["attackAverage"]=8.4,["damageType"]=[[砸伤#1]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu4]],["lv"]=30,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=0,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[尘海翻龙]]},["duanyunfu5"]={["actionText"]=[[$N双手横举$Nw，平扫$n前胸，招式未使老就已打住猝然变招，斧尖直撞$n的小腹。]],["atkList"]=[[duanyunfu5P1]],["attack"]=12.02,["attackAverage"]=9.6,["damageType"]=[[内伤#5]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu5]],["lv"]=50,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=6,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[潜龙推波]]},["duanyunfu6"]={["actionText"]=[[$N不急不缓地转身微蹲，$n见$N露出破绽，急忙抢攻，却突然发现$N的身体已转过来，手中$Nw正迅猛地扫向自己的下盘。]],["atkList"]=[[duanyunfu6P1]],["attack"]=15.05,["attackAverage"]=11.01,["damageType"]=[[砍伤#5]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu6]],["lv"]=80,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=10,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[斧掠平峰]]},["duanyunfu7"]={["actionText"]=[[$N身形微动，就在同一时间自上中下左右砍出五斧，$n见五把$Nw从不同的方位砍向自己，一时间竟不知该如何招架。]],["atkList"]=[[duanyunfu7P1]],["attack"]=16.07,["attackAverage"]=12.2,["damageType"]=[[砍伤#6]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu7]],["lv"]=100,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=15,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[斧封五方]]},["duanyunfu8"]={["actionText"]=[[$N前脚猛地往地上一顿，大地也微微一震，接着举起斧头在头顶急转数圈，$Nw就隐含风云之声平直而沉稳地袭向$n，$n无论向何处闪躲，总看见斧尖离自己不到一尺，不由大惊失色。]],["atkList"]=[[duanyunfu8P1]],["attack"]=24.13,["attackAverage"]=14.29,["damageType"]=[[砍伤#6]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duanyunfu8]],["lv"]=120,["skillId"]=[[duanyunfu]],["tiliCost"]=53,["topLimit"]=18,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[震地撼川]]},["duanzhilixianqin1"]={["actionText"]=[[只见$N右手单指切音，琴声戛然而止，这一招「声销迹灭」，看似悄无声息，实则早已把$n压得喘不过气来。]],["atkList"]=[[duanzhilixianqin1P1]],["attack"]=4.06,["attackAverage"]=4.87,["damageType"]=[[震伤#1]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin1]],["lv"]=0,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=50,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[声销迹灭]]},["duanzhilixianqin10"]={["actionText"]=[[只见$N十指如穿花蝴蝶一般左右拨弦，使出一招「十年生聚」，$n只觉得全身都在$N琴音笼罩之下。]],["atkList"]=[[duanzhilixianqin10P1]],["attack"]=51.46,["attackAverage"]=29.08,["damageType"]=[[震伤#7]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin10]],["lv"]=450,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=240,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[十年生聚]]},["duanzhilixianqin11"]={["actionText"]=[[$N奏法一变，改弦更张，乃是一招「曲终奏雅」，$n反应过来时已被琴音环绕。]],["atkList"]=[[duanzhilixianqin11P1]],["attack"]=58.37,["attackAverage"]=32.8,["damageType"]=[[震伤#8]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin11]],["lv"]=500,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=270,["zhaoId"]=11,["zhaoIdText"]=[[第十一招]],["zhaoName"]=[[曲终奏雅]]},["duanzhilixianqin12"]={["actionText"]=[[$N使出一招「空谷余音」，两目内视，双手离琴，$n耳边随着阵阵弦颤响起震人心魄的琴声。]],["atkList"]=[[duanzhilixianqin12P1]],["attack"]=65.4,["attackAverage"]=36.61,["damageType"]=[[震伤#8]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin12]],["lv"]=550,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=300,["zhaoId"]=12,["zhaoIdText"]=[[第十二招]],["zhaoName"]=[[空谷余音]]},["duanzhilixianqin2"]={["actionText"]=[[只见$N左手托琴，右手轻勾琴弦，一招「至断不僵」将发未发，但是全身劲气已伴随琴音疾卷$n。]],["atkList"]=[[duanzhilixianqin2P1]],["attack"]=6.13,["attackAverage"]=6.11,["damageType"]=[[震伤#2]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin2]],["lv"]=50,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=70,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[至断不僵]]},["duanzhilixianqin3"]={["actionText"]=[[只见$N两手互为交错地弹奏,原本不绝如缕的琴音瞬间变得婉转连绵，高荡起伏，如烈火般一道又一道袭向$n。]],["atkList"]=[[duanzhilixianqin3P1]],["attack"]=10.27,["attackAverage"]=8.18,["damageType"]=[[震伤#2]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin3]],["lv"]=100,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=90,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[绝弦复鸣]]},["duanzhilixianqin4"]={["actionText"]=[[$N双手轻抚琴弦，将一招「大音希声」发挥的淋漓尽致，琴音声若蚊蝇，悄无声息地扑向$n。]],["atkList"]=[[duanzhilixianqin4P1]],["attack"]=12.4,["attackAverage"]=9.86,["damageType"]=[[震伤#3]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin4]],["lv"]=150,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=110,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[大音希声]]},["duanzhilixianqin5"]={["actionText"]=[[$N左手在弦上一滑，右手向外横推而出，这一招「锦里藏针」看似软弱无力，实则暗藏一股排山倒海的内力袭向$n。]],["atkList"]=[[duanzhilixianqin5P1]],["attack"]=18.7,["attackAverage"]=12.37,["damageType"]=[[震伤#4]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin5]],["lv"]=200,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=130,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[锦里藏针]]},["duanzhilixianqin6"]={["actionText"]=[[$N使出一招「银瓶乍破」，只见$N凝气于指猛地一挑，琴音便以迅雷不及掩耳之势地袭向了$n。]],["atkList"]=[[duanzhilixianqin6P1]],["attack"]=25.08,["attackAverage"]=15.33,["damageType"]=[[震伤#4]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin6]],["lv"]=250,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=150,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[银瓶乍破]]},["duanzhilixianqin7"]={["actionText"]=[[$N一招「声振林木」大指连托，奏出数声铿锵有力的琴音，好似平地起了个焦雷，震得$n耳中嗡嗡直响。]],["atkList"]=[[duanzhilixianqin7P1]],["attack"]=31.53,["attackAverage"]=18.54,["damageType"]=[[震伤#5]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin7]],["lv"]=300,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=170,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[声振林木]]},["duanzhilixianqin8"]={["actionText"]=[[$N使出一招「穿云裂石」，右手对着琴弦连劈数下，尖锐的琴声宛若尖刀一般袭向了$n。]],["atkList"]=[[duanzhilixianqin8P1]],["attack"]=38.05,["attackAverage"]=21.93,["damageType"]=[[震伤#6]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin8]],["lv"]=350,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=190,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[穿云裂石]]},["duanzhilixianqin9"]={["actionText"]=[[$N屏气凝神，十指如飞，琴音抑扬顿挫，指法变化莫测，乃是一招「九回肠断」，每一次转调都伴随着强劲的内力袭向$n。]],["atkList"]=[[duanzhilixianqin9P1]],["attack"]=44.65,["attackAverage"]=25.45,["damageType"]=[[震伤#6]],["hit"]=0.7,["hurtPosClass"]=[[default]],["id"]=[[duanzhilixianqin9]],["lv"]=400,["skillId"]=[[duanzhilixianqin]],["tiliCost"]=47,["topLimit"]=210,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[九回肠断]]},["dugujiujian1"]={["actionText"]=[[但见$N挺身而上，$Nw一旋，一招仿佛西风恶剑法的RAN「独钓寒江」NOR直刺$n的$l！]],["atkList"]=[[dugujiujian1P1]],["attack"]=4.2,["attackAverage"]=5.04,["damageType"]=[[刺伤#1]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian1]],["lv"]=10,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[独钓寒江]]},["dugujiujian10"]={["actionText"]=[[$N含笑抱剑，气势庄严，$Nw轻挥，尽融RAN「达摩剑意」NOR为一式，闲舒地刺向$n！]],["atkList"]=[[dugujiujian10P1]],["attack"]=18.06,["attackAverage"]=12.06,["damageType"]=[[刺伤#3]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian10]],["lv"]=140,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=40,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[达摩剑意]]},["dugujiujian11"]={["actionText"]=[[$N举起$Nw运使RAN「太极剑」NOR剑意，划出大大小小无数个圆圈，无穷无尽源源不绝地缠向$n！]],["atkList"]=[[dugujiujian11P1]],["attack"]=20.22,["attackAverage"]=13.17,["damageType"]=[[刺伤#3]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian11]],["lv"]=160,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=45,["zhaoId"]=11,["zhaoIdText"]=[[第十一招]],["zhaoName"]=[[太极剑]]},["dugujiujian12"]={["actionText"]=[[$N神声凝重，$Nw上劈下切左右横扫，挟雷霆万钧之势逼往$n，RAN「伏摩剑」NOR的剑意表露无遗！]],["atkList"]=[[dugujiujian12P1]],["attack"]=22.38,["attackAverage"]=14.31,["damageType"]=[[刺伤#3]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian12]],["lv"]=180,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=50,["zhaoId"]=12,["zhaoIdText"]=[[第十二招]],["zhaoName"]=[[伏摩剑]]},["dugujiujian13"]={["actionText"]=[[却见$N突然虚步提腰，使出酷似武当RAN「蜻蜓点水」NOR的一招！]],["atkList"]=[[dugujiujian13P1]],["attack"]=24.55,["attackAverage"]=15.47,["damageType"]=[[刺伤#4]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian13]],["lv"]=200,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=55,["zhaoId"]=13,["zhaoIdText"]=[[第十三招]],["zhaoName"]=[[蜻蜓点水]]},["dugujiujian14"]={["actionText"]=[[$N运剑如风，剑光霍霍中反攻$n的$l，尝试逼$n自守，剑招似是RAN「伏魔剑」NOR的RAN「龙吞式」NOR。]],["atkList"]=[[dugujiujian14P1]],["attack"]=26.72,["attackAverage"]=16.66,["damageType"]=[[刺伤#4]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian14]],["lv"]=220,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=60,["zhaoId"]=14,["zhaoIdText"]=[[第十四招]],["zhaoName"]=[[伏魔剑]]},["dugujiujian15"]={["actionText"]=[[$N突然运剑如狂，一手关外的RAN「骤雨潇潇剑」NOR，猛然向$n周身乱刺乱削！]],["atkList"]=[[dugujiujian15P1]],["attack"]=28.95,["attackAverage"]=17.86,["damageType"]=[[刺伤#4]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian15]],["lv"]=240,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=70,["zhaoId"]=15,["zhaoIdText"]=[[第十五招]],["zhaoName"]=[[骤雨潇潇剑]]},["dugujiujian16"]={["actionText"]=[[$N满场游走，东刺一剑，西刺一剑，令$n莫明其妙，分不出$N剑法的虚实！]],["atkList"]=[[dugujiujian16P1]],["attack"]=35.69,["attackAverage"]=19.42,["damageType"]=[[刺伤#4]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian16]],["lv"]=260,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=16,["zhaoIdText"]=[[第十六招]],["zhaoName"]=[[虚实相间]]},["dugujiujian17"]={["actionText"]=[[$N抱剑旋身，转到$n身后，杂乱无章地向$n刺出一剑，不知使的是什么剑法！]],["atkList"]=[[dugujiujian17P1]],["attack"]=35.69,["attackAverage"]=20.8,["damageType"]=[[刺伤#5]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian17]],["lv"]=280,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=17,["zhaoIdText"]=[[第十七招]],["zhaoName"]=[[藏背点虚]]},["dugujiujian18"]={["actionText"]=[[$N以手腕运剑，幻出一片剑影，待剑影至$n身前，运剑挺出剑影，点向$n肩膀。]],["atkList"]=[[dugujiujian18P1]],["attack"]=35.69,["attackAverage"]=22.02,["damageType"]=[[刺伤#5]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian18]],["lv"]=300,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=18,["zhaoIdText"]=[[第十八招]],["zhaoName"]=[[乱云式]]},["dugujiujian19"]={["actionText"]=[[$N突然一剑点向$n的$l，虽一剑却暗藏无数后招，逼得$n手足无措，不知如何是好！]],["atkList"]=[[dugujiujian19P1]],["attack"]=35.69,["attackAverage"]=23.12,["damageType"]=[[刺伤#5]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian19]],["lv"]=320,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=19,["zhaoIdText"]=[[第十九招]],["zhaoName"]=[[墨云蓄势]]},["dugujiujian2"]={["actionText"]=[[$N奇诡地向$n挥出RAN「新雨芙蓉」NOR、RAN「霞照紫盖」NOR、RAN「石廪夜悄」NOR、RAN「天柱回风」NOR及RAN「雁戏祝融」NOR衡山宗五神剑！]],["atkList"]=[[dugujiujian2P1]],["attack"]=5.25,["attackAverage"]=5.67,["damageType"]=[[刺伤#1]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian2]],["lv"]=20,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=2,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[回雁岳麓]]},["dugujiujian20"]={["actionText"]=[[$N剑挟刀势，大开大阖地乱砍一通，但招招皆击在$n攻势的破绽，迫得$n不得不守！]],["atkList"]=[[dugujiujian20P1]],["attack"]=35.69,["attackAverage"]=24.1,["damageType"]=[[刺伤#5]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian20]],["lv"]=340,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=20,["zhaoIdText"]=[[第二十招]],["zhaoName"]=[[刀背藏身]]},["dugujiujian21"]={["actionText"]=[[$N反手横剑刺向$n的$l，这似有招似无招的一剑，威力竟然奇大，$n难以看清剑招来势！]],["atkList"]=[[dugujiujian21P1]],["attack"]=35.69,["attackAverage"]=25,["damageType"]=[[刺伤#6]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian21]],["lv"]=360,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=21,["zhaoIdText"]=[[第二十一招]],["zhaoName"]=[[横栏千山]]},["dugujiujian22"]={["actionText"]=[[$N举剑狂挥，迅速无比地点向$n的$l，却令人看不出其所用是什么招式。]],["atkList"]=[[dugujiujian22P1]],["attack"]=35.69,["attackAverage"]=25.81,["damageType"]=[[刺伤#6]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian22]],["lv"]=380,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=22,["zhaoIdText"]=[[第二十二招]],["zhaoName"]=[[无影连环]]},["dugujiujian23"]={["actionText"]=[[$N随手一剑指向$n，落点正是$n的破绽所在，端的是神妙无伦，不可思议！]],["atkList"]=[[dugujiujian23P1]],["attack"]=35.69,["attackAverage"]=26.55,["damageType"]=[[刺伤#6]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian23]],["lv"]=400,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=23,["zhaoIdText"]=[[第二十三招]],["zhaoName"]=[[破海式]]},["dugujiujian24"]={["actionText"]=[[$N脸上突现笑容，似乎已看破$n的武功招式，胸有成竹地一剑刺向$n的$l！]],["atkList"]=[[dugujiujian24P1#dugujiujian24P2]],["attack"]=35.69,["attackAverage"]=27.23,["damageType"]=[[刺伤#6]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian24]],["lv"]=420,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=24,["zhaoIdText"]=[[第二十四招]],["zhaoName"]=[[无为剑式]]},["dugujiujian25"]={["actionText"]=[[$N将$Nw随手一摆，但见$n自己向$Nw撞将上来，神剑之威，实人所难测！]],["atkList"]=[[dugujiujian25P1#dugujiujian25P2]],["attack"]=35.69,["attackAverage"]=27.85,["damageType"]=[[刺伤#7]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian25]],["lv"]=440,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=25,["zhaoIdText"]=[[第二十五招]],["zhaoName"]=[[无双一剑]]},["dugujiujian26"]={["actionText"]=[[但见$N手中$NwHIW破空长吟，平平一剑刺向$n，毫无招式可言。]],["atkList"]=[[dugujiujian26P1#dugujiujian26P2]],["attack"]=35.69,["attackAverage"]=28.43,["damageType"]=[[刺伤#7]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian26]],["lv"]=460,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=26,["zhaoIdText"]=[[第二十六招]],["zhaoName"]=[[凌空平刺]]},["dugujiujian27"]={["actionText"]=[[$N揉身欺近，轻描淡写间随意刺出一剑，简单之极，无招无式。]],["atkList"]=[[dugujiujian27P1#dugujiujian27P2]],["attack"]=35.69,["attackAverage"]=28.96,["damageType"]=[[刺伤#7]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian27]],["lv"]=480,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=27,["zhaoIdText"]=[[第二十七招]],["zhaoName"]=[[无招胜有招]]},["dugujiujian28"]={["actionText"]=[[$N身法飘逸，神态怡然，剑意藏于胸中，手中$NwHIW随意挥洒而出，凌绝九剑已到了收发自如的境界。]],["atkList"]=[[dugujiujian28P1#dugujiujian28P2]],["attack"]=35.69,["attackAverage"]=29.45,["damageType"]=[[刺伤#7]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian28]],["lv"]=500,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=100,["zhaoId"]=28,["zhaoIdText"]=[[第二十八招]],["zhaoName"]=[[剑意挥洒]]},["dugujiujian3"]={["actionText"]=[[$N剑随身转，续而刺出十九剑，竟然是RAN「梦女十九剑」NOR，但奇的是这十九剑便如一招，手法之快，当真匪夷所思！]],["atkList"]=[[dugujiujian3P1]],["attack"]=6.31,["attackAverage"]=6.3,["damageType"]=[[刺伤#1]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian3]],["lv"]=30,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=5,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[梦女十九剑]]},["dugujiujian4"]={["actionText"]=[[RAN$N剑势忽缓而不疏，剑意有余而不尽，化飞絮刀法为一剑，向$n慢慢推去！]],["atkList"]=[[dugujiujian4P1]],["attack"]=7.37,["attackAverage"]=6.94,["damageType"]=[[刺伤#1]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian4]],["lv"]=40,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=10,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[恒流不绝]]},["dugujiujian5"]={["actionText"]=[[RAN$N剑意突焕气象森严，便似千军万马奔驰而来，长枪大戟，黄沙千里，尽括嵩山剑势击向$n的$l！]],["atkList"]=[[dugujiujian5P1]],["attack"]=8.44,["attackAverage"]=7.58,["damageType"]=[[刺伤#2]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian5]],["lv"]=50,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=15,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[嵩山不老松]]},["dugujiujian6"]={["actionText"]=[[却见$N身随剑走，左边一拐，右边一弯，剑招也是越转越加狠辣，竟化RAN「天河十八曲」NOR为一剑攻向$n！]],["atkList"]=[[dugujiujian6P1]],["attack"]=9.51,["attackAverage"]=8.22,["damageType"]=[[刺伤#2]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian6]],["lv"]=60,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=20,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[天河十八曲]]},["dugujiujian7"]={["actionText"]=[[$N剑招突变，使出RAN「剑来满雁惊」NOR，削向$n的$l，怎知剑到中途，突然转向，大出$n意料之外！]],["atkList"]=[[dugujiujian7P1]],["attack"]=11.64,["attackAverage"]=9.04,["damageType"]=[[刺伤#2]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian7]],["lv"]=80,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=25,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[剑来满雁惊]]},["dugujiujian8"]={["actionText"]=[[$N吐气开声，一招似是RAN「独劈华山」NOR，手中$Nw向下斩落，直劈向$n的$l！]],["atkList"]=[[dugujiujian8P1]],["attack"]=13.77,["attackAverage"]=9.97,["damageType"]=[[刺伤#2]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian8]],["lv"]=100,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=30,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[独劈华山]]},["dugujiujian9"]={["actionText"]=[[$N手中$Nw越转越快，使的居然是RAN「千山埋骨驱云剑」NOR，剑式有如云卷雾涌，旁观者不由得目为之眩！]],["atkList"]=[[dugujiujian9P1]],["attack"]=15.92,["attackAverage"]=10.99,["damageType"]=[[刺伤#3]],["hit"]=0.75,["hurtPosClass"]=[[default]],["id"]=[[dugujiujian9]],["lv"]=120,["skillId"]=[[dugujiujian]],["tiliCost"]=47,["topLimit"]=35,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[千山埋骨驱云剑]]},["duhuojian1"]={["actionText"]=[[$N使一式「不绝若线」，身形一晃，疾掠而上，手中$Nw剑走偏锋，朝着$n狠狠刺去。]],["atkList"]=[[duhuojian1P1]],["attack"]=4,["attackAverage"]=4.8,["damageType"]=[[砍伤#1]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duhuojian1]],["lv"]=0,["skillId"]=[[duhuojian]],["tiliCost"]=50,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[不绝若线]]},["duhuojian10"]={["actionText"]=[[$N使出一招「玉石俱摧」，只攻不守，手中$Nw化作数道寒光，招招直逼$n要害。]],["atkList"]=[[duhuojian10P1]],["attack"]=42.16,["attackAverage"]=27.35,["damageType"]=[[砍伤#6]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duhuojian10]],["lv"]=450,["skillId"]=[[duhuojian]],["tiliCost"]=50,["topLimit"]=180,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[玉石俱摧]]},["duhuojian11"]={["actionText"]=[[$N一招「沉冤昭雪」，身形跃在半空，手中$Nw朝着$n横削而出。]],["atkList"]=[[duhuojian11P1]],["attack"]=46.64,["attackAverage"]=29.95,["damageType"]=[[砍伤#6]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[duhuojian11]],["lv"]=500,["skillId"]=[[duhuojian]],["tiliCost"]=50,["topLimit"]=200,["zhaoId"]=11,["zhaoIdText"]=[[第十一招]],["zhaoName"]=[[沉冤昭雪]]},["duhuojian2"]={["