[feixianjianfa9]],["lv"]=250,["skillId"]=[[feixianjianfa]],["tiliCost"]=43,["topLimit"]=120,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[柳暗花明]]},["fengbaojinxingqu1"]={["actionText"]=[[只见$N毫无花俏，一个跳步逼近后，抬手便向$n的胸口就是一斩。这一刀劈得$Nw呼呼作响，正是一记「寒风之呼啸」。]],["atkList"]=[[fengbaojinxingqu1P1]],["attack"]=5.3,["attackAverage"]=6.36,["damageType"]=[[砍伤#1]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu1]],["lv"]=0,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[寒风之呼啸]]},["fengbaojinxingqu2"]={["actionText"]=[[$N一式「飓风之侵袭」，身子往前一探，只见白光一闪，手中利刃飓风肆虐般斩向$n的头颅。]],["atkList"]=[[fengbaojinxingqu2P1]],["attack"]=8.93,["attackAverage"]=8.54,["damageType"]=[[砍伤#2]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu2]],["lv"]=100,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=11,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[飓风之侵袭]]},["fengbaojinxingqu3"]={["actionText"]=[[只见$N反手握刀，须臾间一记疾风前斩，斩向$n的腰间，当真是云散烈风，势不可挡。正是一招「疾风之挺进」。]],["atkList"]=[[fengbaojinxingqu3P1]],["attack"]=14.61,["attackAverage"]=11.54,["damageType"]=[[砍伤#3]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu3]],["lv"]=150,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=26,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[疾风之挺进]]},["fengbaojinxingqu4"]={["actionText"]=[[$N使出一记「晚风之吹拂」，闲庭信步，一挑一刺，只见刀光掠闪，刀芒仿佛在半空化成一股清风，向着$n穿透而来。]],["atkList"]=[[fengbaojinxingqu4P1]],["attack"]=22.21,["attackAverage"]=15.32,["damageType"]=[[刺伤#4]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu4]],["lv"]=200,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=47,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[晚风之吹拂]]},["fengbaojinxingqu5"]={["actionText"]=[[$N身形犹如旋风起舞，忽上忽下，一式「旋风之律动」使出，动作优雅，不紧不慢，手中$Nw一挥而下，直击$n的心口。]],["atkList"]=[[fengbaojinxingqu5P1]],["attack"]=31.79,["attackAverage"]=19.88,["damageType"]=[[砍伤#4]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu5]],["lv"]=250,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=74,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[旋风之律动]]},["fengbaojinxingqu6"]={["actionText"]=[[$N使一出一记「狂风之肆虐」，突然身形暴涨，快若惊鸿，手中$Nw一摆似是一股狂风倾泻而出，直直向$n兜头削去。]],["atkList"]=[[fengbaojinxingqu6P1]],["attack"]=43.43,["attackAverage"]=25.25,["damageType"]=[[砍伤#5]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu6]],["lv"]=300,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=105,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[狂风之肆虐]]},["fengbaojinxingqu7"]={["actionText"]=[[只听$N大喝一声，高高举起跃起，朝着$n狠狠劈出一刀，刀势刚猛宛如暴风席卷而过。正是一招「暴风之怒号」。]],["atkList"]=[[fengbaojinxingqu7P1]],["attack"]=59.43,["attackAverage"]=31.83,["damageType"]=[[砍伤#6]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu7]],["lv"]=400,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=148,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[暴风之怒号]]},["fengbaojinxingqu8"]={["actionText"]=[[只见$N神情肃穆，身形纹丝不动宛如一尊雕像。蓦然间，$N手持$Nw向前一指，犹如破风前行，令$n倒吸一口凉气。]],["atkList"]=[[fengbaojinxingqu8P1]],["attack"]=77.8,["attackAverage"]=39.53,["damageType"]=[[刺伤#7]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengbaojinxingqu8]],["lv"]=450,["skillId"]=[[fengbaojinxingqu]],["tiliCost"]=53,["topLimit"]=195,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[逆风之前行]]},["fengmozhangfa1"]={["actionText"]=[[$N微一躬身，$Nw携带着刺耳的飕飕风声，擦地扫向$n的脚踝。]],["atkList"]=[[fengmozhangfa1P1]],["attack"]=2.8,["attackAverage"]=3.36,["damageType"]=[[挫伤#1]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengmozhangfa1]],["lv"]=0,["skillId"]=[[fengmozhangfa]],["tiliCost"]=57,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[地堂横扫]]},["fengmozhangfa2"]={["actionText"]=[[$N右手托住杖端，左掌居中一击，令其凭惯性倒向$n的肩头。]],["atkList"]=[[fengmozhangfa2P1]],["attack"]=4.2,["attackAverage"]=4.2,["damageType"]=[[挫伤#2]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[fengmozhangfa2]],["lv"]=10,["skillId"]=[[fengmozhangfa]],