xt"]=[[$N力贯$Nw，一棍抡满，瞧着天灵盖直砸而下，以刚猛劲力压制$n所有攻势。]],["atkList"]=[[itavanaBreakBarrier6P1]],["attack"]=33.44,["attackAverage"]=35.48,["damageType"]=[[震伤#4]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[itavanaBreakBarrier6]],["lv"]=300,["skillId"]=[[itavanaBreakBarrier]],["tiliCost"]=50,["topLimit"]=128,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[枯荣轮转]]},["itavanaBreakBarrier7"]={["actionText"]=[[一招「诛戮天魔」，$N化出万千棍影，遮天蔽日，将$n罩在中央,避无可避。]],["atkList"]=[[itavanaBreakBarrier7P1]],["attack"]=36.04,["attackAverage"]=36.59,["damageType"]=[[震伤#5]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[itavanaBreakBarrier7]],["lv"]=400,["skillId"]=[[itavanaBreakBarrier]],["tiliCost"]=50,["topLimit"]=139,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[诛戮天魔]]},["itavanaBreakBarrier8"]={["actionText"]=[[$N一招「骨腾魂飞」，高高举起$Nw，忽地怔住，又出人不意地猛然落下，刚猛的劲气直击$n。]],["atkList"]=[[itavanaBreakBarrier8P1]],["attack"]=39.09,["attackAverage"]=37.88,["damageType"]=[[震伤#6]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[itavanaBreakBarrier8]],["lv"]=450,["skillId"]=[[itavanaBreakBarrier]],["tiliCost"]=50,["topLimit"]=151,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[骨腾魂飞]]},["itavanaBreakBarrier9"]={["actionText"]=[[$N双目一闭，好似入定，忽然$Nw长驱径入直击$n的胸中大穴，令$n措手不及。]],["atkList"]=[[itavanaBreakBarrier9P1]],["attack"]=42.61,["attackAverage"]=39.35,["damageType"]=[[震伤#7]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[itavanaBreakBarrier9]],["lv"]=500,["skillId"]=[[itavanaBreakBarrier]],["tiliCost"]=50,["topLimit"]=165,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[终获悉地]]},["jiangxingpoegou1"]={["actionText"]=[[$N双手交叉，纵身行前，运一招「断骨铰」，将$Nw平挥而出，激发出两道刚猛环劲，成夹击之势铰向$n。]],["atkList"]=[[jiangxingpoegou1P1]],["attack"]=10.21,["attackAverage"]=12.25,["damageType"]=[[刺伤#1]],["hit"]=0.3,["hurtPosClass"]=[[default]],["id"]=[[jiangxingpoegou1]],["lv"]=0,["skillId"]=[[jiangxingpoegou]],["tiliCost"]=53,["topLimit"]=70,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[断骨铰]]},["jiangxingpoegou2"]={["actionText"]=[[