illId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[葵花初绽]]},["kuihuadafa10"]={["actionText"]=[[突然$N手中$Nw向上一撩，就在$n微一分神之际直取$n的$l，势道劲急无伦。]],["atkList"]=[[kuihuadafa10P1]],["attack"]=23.04,["attackAverage"]=16.4,["damageType"]=[[刺伤#4]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa10]],["lv"]=140,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=35,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[摘云挑]]},["kuihuadafa11"]={["actionText"]=[[就在$n一呆之际，$N向右跃开两尺，右足刚著地，身子跟著弹起，刷刷两剑，向$n攻去。]],["atkList"]=[[kuihuadafa11P1]],["attack"]=23.07,["attackAverage"]=17.42,["damageType"]=[[刺伤#4]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa11]],["lv"]=160,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=40,["zhaoId"]=11,["zhaoIdText"]=[[第十一招]],["zhaoName"]=[[腾转连剑]]},["kuihuadafa12"]={["actionText"]=[[$N忽然化身为二，分出左右两个身影高速滑向$n，手中$Nw幻化不定，直刺$n的$l。]],["atkList"]=[[kuihuadafa12P1]],["attack"]=25.03,["attackAverage"]=18.47,["damageType"]=[[刺伤#5]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa12]],["lv"]=180,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=45,["zhaoId"]=12,["zhaoIdText"]=[[第十二招]],["zhaoName"]=[[双影幻剑]]},["kuihuadafa13"]={["actionText"]=[[$n只觉眼前一花，似乎见到$N身形一幌，但随即又见$N回到原地，却似从未离开。]],["atkList"]=[[kuihuadafa13P1]],["attack"]=27,["attackAverage"]=19.54,["damageType"]=[[刺伤#5]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa13]],["lv"]=200,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=50,["zhaoId"]=13,["zhaoIdText"]=[[第十三招]],["zhaoName"]=[[燕归巢]]},["kuihuadafa14"]={["actionText"]=[[$N一声尖叫，飞身纵起，在半空中一转，快绝无比的飞落下来，手中$Nw破空直刺$n$l。]],["atkList"]=[[kuihuadafa14P1]],["attack"]=28.97,["attackAverage"]=20.63,["damageType"]=[[刺伤#5]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa14]],["lv"]=220,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=55,["zhaoId"]=14,["zhaoIdText"]=[[第十四招]],["zhaoName"]=[[腾云归凡]]},["kuihuadafa15"]={["actionText"]=[[$N忽然化身为二，分出上下两个身影高速滑向$n，手中$Nw变幻莫测，直刺$n的$l。]],["atkList"]=[[kuihuadafa15P1]],["attack"]=31.08,["attackAverage"]=21.74,["damageType"]=[[刺伤#6]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa15]],["lv"]=240,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=75,["zhaoId"]=15,["zhaoIdText"]=[[第十五招]],["zhaoName"]=[[结伴成双]]},["kuihuadafa16"]={["actionText"]=[[$N的身形如鬼如魅，飘忽来去，直似轻烟，手中的$Nw却总是对着$n身子。]],["atkList"]=[[kuihuadafa16P1]],["attack"]=33.17,["attackAverage"]=22.87,["damageType"]=[[刺伤#6]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa16]],["lv"]=260,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=90,["zhaoId"]=16,["zhaoIdText"]=[[第十六招]],["zhaoName"]=[[烟云骤落]]},["kuihuadafa17"]={["actionText"]=[[$N一声冷笑，蓦地里疾冲上前，当真是动如脱兔，一瞬之间，与$n相距已不到一尺，两人的鼻子几乎要碰在一起。]],["atkList"]=[[kuihuadafa17P1]],["attack"]=35.23,["attackAverage"]=24.01,["damageType"]=[[刺伤#6]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa17]],["lv"]=280,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=100,["zhaoId"]=17,["zhaoIdText"]=[[第十七招]],["zhaoName"]=[[咫尺落花]]},["kuihuadafa18"]={["actionText"]=[[$N右手伸出，在$n手腕上迅速无比的一按，跟着手臂回转，又在$n手肘下一推。]],["atkList"]=[[kuihuadafa18P1#kuihuadafa18P2]],["attack"]=37.29,["attackAverage"]=25.16,["damageType"]=[[刺伤#7]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa18]],["lv"]=300,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=110,["zhaoId"]=18,["zhaoIdText"]=[[第十八招]],["zhaoName"]=[[飞影流云]]},["kuihuadafa19"]={["actionText"]=[[$N一剑挺刺，极尽清雅，神态之中，竟大有华山女弟子所学‘天女剑十九式’的风姿，只是带着三分阴森森的邪气。]],["atkList"]=[[kuihuadafa19P1#kuihuadafa19P2#kuihuadafa19P3]],["attack"]=39.37,["attackAverage"]=26.33,["damageType"]=[[刺伤#7]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[kuihuadafa19]],["lv"]=320,["skillId"]=[[kuihuadafa]],["tiliCost"]=43,["topLimit"]=120,["zhaoId"]=19,["zhaoIdText"]=[[第十九招]],["zhaoName"]=[[冰心初融]]},["kuihuadafa2"]={["actionText"]=[[但见红影闪处，$N手中的$Nw向$n的$l直戳而来，势如奔雷，避不可避。]],["atkList"]=[[kuihuadafa2P1]],["attack"]=8.36,["