d"]=[[lanshashou8]],["lv"]=250,["skillId"]=[[lanshashou]],["tiliCost"]=52,["topLimit"]=40,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[掌影千幻]]},["lanshashou9"]={["actionText"]=[[$N仰天一声狂啸，双掌携带着万古冰坚直直贯向$n。]],["atkList"]=[[lanshashou9P1]],["attack"]=15.27,["attackAverage"]=7.28,["damageType"]=[[瘀伤#9]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[lanshashou9]],["lv"]=300,["skillId"]=[[lanshashou]],["tiliCost"]=52,["topLimit"]=60,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[万古冰川]]},["lanyeshenzhang1"]={["actionText"]=[[$N步下虚浮，左右各走三步，步伐渐乱，上身侧倾，犹如一个醉汉在道中风耍，缓缓朝$n靠近，刚至五步内，$N猛然握拳发力，一招打在了$n$l。]],["atkList"]=[[lanyeshenzhang1P1]],["attack"]=3,["attackAverage"]=3.6,["damageType"]=[[瘀伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang1]],["lv"]=0,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[三星捧月]]},["lanyeshenzhang10"]={["actionText"]=[[$N将真气凝聚于掌心，踏步向前，信手击出，每一击都带着呼呼呼的气流声，但又非真气外放那样耗费内力，此等巧思当真少见。]],["atkList"]=[[lanyeshenzhang10P1]],["attack"]=20.17,["attackAverage"]=13.8,["damageType"]=[[瘀伤#5]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang10]],["lv"]=200,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=115,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[夜掠空山]]},["lanyeshenzhang11"]={["actionText"]=[[$N一个小碎步屈身向前，使出一招RAN「夜阑人静」NOR，突然击向$n$l。]],["atkList"]=[[lanyeshenzhang11P1]],["attack"]=22.57,["attackAverage"]=15.01,["damageType"]=[[瘀伤#6]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang11]],["lv"]=230,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=125,["zhaoId"]=11,["zhaoIdText"]=[[第十一招]],["zhaoName"]=[[夜阑人静]]},["lanyeshenzhang12"]={["actionText"]=[[$N闪电般突然跳向$n，一掌击出，然后又折身转向，在即将远离的时候又连续打出几掌，虚虚实实，让人目眩神迷。]],["atkList"]=[[lanyeshenzhang12P1]],["attack"]=24.23,["attackAverage"]=16.18,["damageType"]=[[瘀伤#6]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang12]],["lv"]=260,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=140,["zhaoId"]=12,["zhaoIdText"]=[[第十二招]],["zhaoName"]=[[星灯落谷]]},["lanyeshenzhang13"]={["actionText"]=[[$N使出一招RAN「霜重露浓」NOR，突然击向$n$l，这一招绵里藏针、掌风中似乎带有吸附力，让受击者一分难受。]],["atkList"]=[[lanyeshenzhang13P1]],["attack"]=26.65,["attackAverage"]=17.4,["damageType"]=[[瘀伤#7]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang13]],["lv"]=290,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=150,["zhaoId"]=13,["zhaoIdText"]=[[第十三招]],["zhaoName"]=[[霜重露浓]]},["lanyeshenzhang14"]={["actionText"]=[[$N变掌成拳，打向$n的前胸，然后又快速变拳为掌，拍向$n的腹部和后心，这是揽夜神掌的著名招式RAN「漏断声咽」NOR。]],["atkList"]=[[lanyeshenzhang14P1]],["attack"]=28.34,["attackAverage"]=18.58,["damageType"]=[[瘀伤#7]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang14]],["lv"]=320,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=165,["zhaoId"]=14,["zhaoIdText"]=[[第十四招]],["zhaoName"]=[[漏断声咽]]},["lanyeshenzhang15"]={["actionText"]=[[$N一个冷笑，左手画了个圈，然后右手以一种快到不可思议的速度从圈里穿出来，击向$n$l，这是揽夜神掌的杀招之一RAN「懒抛流光」NOR。]],["atkList"]=[[lanyeshenzhang15P1]],["attack"]=30.79,["attackAverage"]=19.81,["damageType"]=[[瘀伤#8]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang15]],["lv"]=360,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=175,["zhaoId"]=15,["zhaoIdText"]=[[第十五招]],["zhaoName"]=[[懒抛流光]]},["lanyeshenzhang16"]={["actionText"]=[[$N一个小碎步屈身向前，将真气灌注双臂，使出一招RAN「夜梦浮生」NOR，击向$n$l，这一击看似不疾不徐，却让人有种避无可避之感！]],["atkList"]=[[lanyeshenzhang16P1]],["attack"]=32.5,["attackAverage"]=21.01,["damageType"]=[[瘀伤#8]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang16]],["lv"]=400,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=190,["zhaoId"]=16,["zhaoIdText"]=[[第十六招]],["zhaoName"]=[[夜梦浮生]]},["lanyeshenzhang17"]={["actionText"]=[[$N一声清啸，将真气灌注双臂，使出一招RAN「惊回千里」NOR，击向$n周身要害，这一击苍茫浑厚、遮天蔽月，让人有种闭目待死的绝望感。]],["atkList"]=[[lanyeshenzhang17P1]],["attack"]=34.98,["attackAverage"]=22.24,["damageType"]=[[瘀伤#9]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang17]],["lv"]=450,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=200,["zhaoId"]=17,["zhaoIdText"]=[[第十七招]],["zhaoName"]=[[惊回千里]]},["lanyeshenzhang18"]={["actionText"]=[[$N长啸一声，将浑身之力聚于左掌，右掌先出，攻入$n胸前，左掌下刺腹部，威力之强，足以震碎寻常人五脏肺腑，这正是揽夜神掌最厉害的一招「食月无夜」。]],["atkList"]=[[lanyeshenzhang18P1]],["attack"]=37.52,["attackAverage"]=23.51,["damageType"]=[[瘀伤#9]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang18]],["lv"]=500,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=215,["zhaoId"]=18,["zhaoIdText"]=[[第十八招]],["zhaoName"]=[[食月无夜]]},["lanyeshenzhang2"]={["actionText"]=[[$N微微摇了摇头，身影一闪，双手对穿，使出一招RAN「月影中天」NOR，双掌如利剑，直刺$n胸前。]],["atkList"]=[[lanyeshenzhang2P1]],["attack"]=4.52,["attackAverage"]=4.51,["damageType"]=[[瘀伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang2]],["lv"]=20,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=15,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[月影中天]]},["lanyeshenzhang3"]={["actionText"]=[[$N伸了个懒腰，往前大步一跨，双掌左右画圈，下盘稳如月桂生根，顿时连击数掌，掌风凌厉，将$n击倒在地。]],["atkList"]=[[lanyeshenzhang3P1]],["attack"]=6.8,["attackAverage"]=5.73,["damageType"]=[[瘀伤#2]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang3]],["lv"]=40,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=25,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[桂托天河]]},["lanyeshenzhang4"]={["actionText"]=[[$N冷笑一声，使出一招RAN「夜火烧云」NOR，悄无声息的闪身至$n身侧，当即呼出一掌，右腿横扫，让$n措手不及。]],["atkList"]=[[lanyeshenzhang4P1]],["attack"]=8.35,["attackAverage"]=6.8,["damageType"]=[[瘀伤#2]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang4]],["lv"]=60,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=40,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[夜火烧云]]},["lanyeshenzhang5"]={["actionText"]=[[$N侧倒在地，手腕翻转，似醒非醒，正如同醉汉卧地，抱壶灌酒，实则暗暗凝气，时机一到，$N骤然睁大双眼，当即坐起一掌推出，势如破竹，直攻$n$l。]],["atkList"]=[[lanyeshenzhang5P1]],["attack"]=10.66,["attackAverage"]=8,["damageType"]=[[瘀伤#3]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang5]],["lv"]=80,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=50,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[醉失天地]]},["lanyeshenzhang6"]={["actionText"]=[[$N腾空跳起，如踏浪行舟般使出一招RAN「踏云摘月」NOR，一手为爪，一手为掌，立即擒住了$n胸口的衣襟，紧接着一掌打下，浑然天成。]],["atkList"]=[[lanyeshenzhang6P1]],["attack"]=12.23,["attackAverage"]=9.11,["damageType"]=[[瘀伤#3]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang6]],["lv"]=100,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=65,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[踏云摘月]]},["lanyeshenzhang7"]={["actionText"]=[[$N双掌回旋，俯身一勾，使出一招RAN「云海捞月」NOR，如鱼跃龙门，迅速游窜至$n身侧，左右两臂反勾，将$n反摔在地，双掌同时击下。]],["atkList"]=[[lanyeshenzhang7P1]],["attack"]=14.57,["attackAverage"]=10.31,["damageType"]=[[瘀伤#4]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang7]],["lv"]=125,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=75,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[云海捞月]]},["lanyeshenzhang8"]={["actionText"]=[[$N疾步向前冲去，一招RAN「罢饮江河」NOR向前直劈，左右诱敌，趁$n混乱之时打出两掌，第一掌力道深厚，第二掌则如隔山打牛。]],["atkList"]=[[lanyeshenzhang8P1]],["attack"]=16.18,["attackAverage"]=11.45,["damageType"]=[[瘀伤#4]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang8]],["lv"]=150,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=90,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[罢饮江河]]},["lanyeshenzhang9"]={["actionText"]=[[$N双拳紧握，两臂僵直，侧身连翻使出一招RAN「月下鼓擂」NOR，击中了$n双肩，击中的同时化拳为掌，内息一沉，迅猛推出，直击$n左肋。]],["atkList"]=[[lanyeshenzhang9P1]],["attack"]=18.54,["attackAverage"]=12.65,["damageType"]=[[瘀伤#5]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[lanyeshenzhang9]],["lv"]=175,["skillId"]=[[lanyeshenzhang2]],["tiliCost"]=48,["topLimit"]=100,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[月下鼓擂]]},["liangyijianfa1"]={["actionText"]=[[$N剑尖剑芒暴长，一招RAN「法分玄素」NOR，手中$Nw自左下大开大阖，一剑向右上向$n的$l。]],["atkList"]=[[liangyijianfa1P1]],["attack"]=4.2,["attackAverage"]=5.04,["damageType"]=[[刺伤#1]],["hit"]=1.5,["hurtPosClass"]=[[defau