,["topLimit"]=1,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[浪起湖心]]},["tiangangzhixuefa2"]={["actionText"]=[[$N双手上下起落，俯身掠向$n，一式「瀑落清潭」，左手化掌成指，汹涌袭向$n的$l。]],["atkList"]=[[tiangangzhixuefa2P1]],["attack"]=2.04,["attackAverage"]=1.94,["damageType"]=[[瘀伤#2]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[tiangangzhixuefa2]],["lv"]=10,["skillId"]=[[tiangangzhixuefa]],["tiliCost"]=50,["topLimit"]=2,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[瀑落清潭]]},["tiangangzhixuefa3"]={["actionText"]=[[$N左手由拳变掌，右手扭曲如灵蛇，一式「龟蛇竞渡」，左右并用，拍向$n的$l。]],["atkList"]=[[tiangangzhixuefa3P1]],["attack"]=2.88,["attackAverage"]=2.45,["damageType"]=[[内伤#3]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[tiangangzhixuefa3]],["lv"]=20,["skillId"]=[[tiangangzhixuefa]],["tiliCost"]=50,["topLimit"]=5,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[龟蛇竞渡]]},["tiangangzhixuefa4"]={["actionText"]=[[$N一式「倒索攀山」，左手抽回，右手前探，戟指点向$n的$l。]],["atkList"]=[[tiangangzhixuefa4P1]],["attack"]=3.73,["attackAverage"]=2.96,["damageType"]=[[砍伤#4]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[tiangangzhixuefa4]],["lv"]=30,["skillId"]=[[tiangangzhixuefa]],["tiliCost"]=50,["topLimit"]=10,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[倒索攀山]]},["tiangangzhixuefa5"]={["actionText"]=[[$N使一式「闪现雷鸣」，身影变幻不定地掠至$n身后，猛地拍向$n的$l。]],["atkList"]=[[tiangangzhixuefa5P1]],["attack"]=5.43,["attackAverage"]=3.67,["damageType"]=[[砍伤#5]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[tiangangzhixuefa5]],["lv"]=50,["skillId"]=[[tiangangzhixuefa]],["tiliCost"]=50,["topLimit"]=20,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[闪现雷鸣]]},["tiangangzhixuefa6"]={["actionText"]=[[$N两臂大开大阖，吸一口气，一式「地动山摇」，劲力透彻，双手快速一拨，激出数道劲气逼向$n的$l。]],["atkList"]=[[tiangangzhixuefa6P1]],["attack"]=7.16,["attackAverage"]=4.49,["damageType"]=[[瘀伤#8]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[tiangangzhixuefa6]],["lv"]=70,["skillId"]=[[tiangangzhixuefa]],["tiliCost"]=50,["topLimit"]=40,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[地动山摇]]},