=[[wuliangjianfa3]],["lv"]=80,["skillId"]=[[wuliangjianfa]],["tiliCost"]=43,["topLimit"]=10,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[缘无量]]},["wuliangjianfa4"]={["actionText"]=[[$N身形一晃疾掠而上，手中$Nw龙吟一声，一招「大海无量」，对准$n$l连递数剑。]],["atkList"]=[[wuliangjianfa4P1]],["attack"]=10.56,["attackAverage"]=6.78,["damageType"]=[[刺伤#4]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuliangjianfa4]],["lv"]=120,["skillId"]=[[wuliangjianfa]],["tiliCost"]=43,["topLimit"]=20,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[大海无量]]},["wuliangjianfa5"]={["actionText"]=[[$N一招「天地无量」扑向$n，如影相随，手中$Nw“铮”然有声，往$n的$l刺去。]],["atkList"]=[[wuliangjianfa5P1]],["attack"]=13.62,["attackAverage"]=8.69,["damageType"]=[[刺伤#5]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuliangjianfa5]],["lv"]=140,["skillId"]=[[wuliangjianfa]],["tiliCost"]=43,["topLimit"]=30,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[天地无量]]},["wuliangjianfa6"]={["actionText"]=[[$N一个侧身，一招「日月无量」，手中$Nw疾往斜上挑起，直指$n的$l。]],["atkList"]=[[wuliangjianfa6P1]],["attack"]=16.7,["attackAverage"]=10.58,["damageType"]=[[刺伤#6]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuliangjianfa6]],["lv"]=180,["skillId"]=[[wuliangjianfa]],["tiliCost"]=43,["topLimit"]=40,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[日月无量]]},["wuliangjianfa7"]={["actionText"]=[[$N微微一个转身，手中$Nw却已自肋下穿出，一招「乾坤无量」，罩向$n的$l。]],["atkList"]=[[wuliangjianfa7P1]],["attack"]=22.84,["attackAverage"]=12.99,["damageType"]=[[刺伤#7]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuliangjianfa7]],["lv"]=220,["skillId"]=[[wuliangjianfa]],["tiliCost"]=43,["topLimit"]=50,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[乾坤无量]]},["wulongjiaozhutui1"]={["actionText"]=[[$N将重心置于左脚，右腿离地蓄劲，身形一转借势使出一招「碾足掌」，右腿如鞭子般扫向$n。]],["atkList"]=[[wulongjiaozhutui1P1]],["attack"]=1.3,["attackAverage"]=1.56,["damageType"]=[[砸伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui1]],["lv"]=0,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[碾足掌]]},["wulongjiaozhutui10"]={["actionText"]=[[$N突然使出一招「转莲花」，整个人腾空而起而起，双足连环圈转，转出漫天腿影攻向$n。]],["atkList"]=[[wulongjiaozhutui10P1]],["attack"]=13.35,["attackAverage"]=8.73,["damageType"]=[[内伤#7]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui10]],["lv"]=450,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=90,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[转莲花]]},["wulongjiaozhutui2"]={["actionText"]=[[$N气贯丹田，随后将全身之力汇聚于一点，使出一招「亮鞋底」，狠狠地蹬向$n。]],["atkList"]=[[wulongjiaozhutui2P1]],["attack"]=2.61,["attackAverage"]=2.35,["damageType"]=[[砸伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui2]],["lv"]=10,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=10,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[亮靴底]]},["wulongjiaozhutui3"]={["actionText"]=[[$N双腿一前一后，前脚虚晃踢出，不待落下，右脚紧跟着凌空踢出，一式「垫前踢」重重踢向$n。]],["atkList"]=[[wulongjiaozhutui3P1]],["attack"]=3.92,["attackAverage"]=3.13,["damageType"]=[[砸伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui3]],["lv"]=30,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=20,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[垫前踢]]},["wulongjiaozhutui4"]={["actionText"]=[[$N一式「斜向蹉」，左脚斜踹，随即向右前方落步，右脚迅速发力踢向$n。]],["atkList"]=[[wulongjiaozhutui4P1]],["attack"]=5.25,["attackAverage"]=3.92,["damageType"]=[[砸伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui4]],["lv"]=60,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=30,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[斜向蹉]]},["wulongjiaozhutui5"]={["actionText"]=[[$N欺身向前，以风卷残云之势连扫数脚，这一招「鱼鳞云」腿法变化莫测，直逼$n。]],["atkList"]=[[wulongjiaozhutui5P1]],["attack"]=6.58,["attackAverage"]=4.72,["damageType"]=[[抓伤#4]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui5]],["lv"]=100,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=40,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[鱼鳞云]]},["wulongjiaozhutui6"]={["actionText"]=[[$N身体凌空而起，使出一招「双展翅」，先起左脚直踢$n，乘势转身再起右脚，两击相辅相成，环环相扣。]],["atkList"]=[[wulongjiaozhutui6P1]],["attack"]=7.92,["attackAverage"]=5.52,["damageType"]=[[抓伤#5]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui6]],["lv"]=150,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=50,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[双展翅]]},["wulongjiaozhutui7"]={["actionText"]=[[$N身形晃动，使出一招「四角台」，两腿忽左忽右交叉踢起，招招不离$n。]],["atkList"]=[[wulongjiaozhutui7P1]],["attack"]=9.26,["attackAverage"]=6.32,["damageType"]=[[内伤#5]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui7]],["lv"]=210,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=60,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[四台角]]},["wulongjiaozhutui8"]={["actionText"]=[[只见$N倒背双手直奔$n，眨眼间已朝$n踢出连环八脚，招招不离下盘，此招正是「八抬轿」。]],["atkList"]=[[wulongjiaozhutui8P1]],["attack"]=10.62,["attackAverage"]=7.12,["damageType"]=[[内伤#6]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui8]],["lv"]=280,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=70,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[八抬轿]]},["wulongjiaozhutui9"]={["actionText"]=[[$N向前一倒使出一记空翻，右腿划了一个大弧，从上而下劈向$n，此招唤作「醉花间」，形醉而神不醉。]],["atkList"]=[[wulongjiaozhutui9P1]],["attack"]=11.98,["attackAverage"]=7.93,["damageType"]=[[内伤#7]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[wulongjiaozhutui9]],["lv"]=360,["skillId"]=[[wulongjiaozhutui]],["tiliCost"]=47,["topLimit"]=80,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[醉花间]]},["wuluoqingyanzhang1"]={["actionText"]=[[$N屏息静气，手起一掌「轻烟袅袅」，轻轻柔柔地拍向$n。]],["atkList"]=[[wuluoqingyanzhang1P1]],["attack"]=0,["attackAverage"]=0,["damageType"]=[[瘀伤#1]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuluoqingyanzhang1]],["lv"]=0,["skillId"]=[[wuluoqingyanzhang]],["tiliCost"]=50,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[轻烟袅袅]]},["wuluoqingyanzhang2"]={["actionText"]=[[$N轻轻浅笑，绕到$n身后，左手做势温柔轻拥$n腰间。$n蹙眉急躲，$N右手一招「烟雾缭绕」，无声无息向$n的$l拍到。]],["atkList"]=[[wuluoqingyanzhang2P1]],["attack"]=2.4,["attackAverage"]=1.44,["damageType"]=[[瘀伤#3]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuluoqingyanzhang2]],["lv"]=20,["skillId"]=[[wuluoqingyanzhang]],["tiliCost"]=50,["topLimit"]=0,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[烟雾缭绕]]},["wuluoqingyanzhang3"]={["actionText"]=[[$N一招「烟海云涛」，双掌幻化出一片掌影，如一阵轻烟，将$n细细密密地笼罩于内。]],["atkList"]=[[wuluoqingyanzhang3P1]],["attack"]=4.8,["attackAverage"]=2.88,["damageType"]=[[瘀伤#5]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuluoqingyanzhang3]],["lv"]=30,["skillId"]=[[wuluoqingyanzhang]],["tiliCost"]=50,["topLimit"]=3,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[烟海云涛]]},["wuluoqingyanzhang4"]={["actionText"]=[[$N返身越出圈外，回首一招「云烟渺渺」，远远地向$n的$l轻轻拍出两掌，掌风刮到，陡然变盛直让$n呼不出气来。]],["atkList"]=[[wuluoqingyanzhang4P1]],["attack"]=7.21,["attackAverage"]=4.32,["damageType"]=[[瘀伤#6]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuluoqingyanzhang4]],["lv"]=50,["skillId"]=[[wuluoqingyanzhang]],["tiliCost"]=50,["topLimit"]=4,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[云烟渺渺]]},["wuluoqingyanzhang5"]={["actionText"]=[[$N左掌从右掌内围翻出，轻飘飘地向$n拍去，看到$n起手招架，右掌却自胸口疾速圈出，一招「烟雾弥漫」，赶超左掌，拍向$n的$l。]],["atkList"]=[[wuluoqingyanzhang5P1]],["attack"]=9.62,["attackAverage"]=5.77,["damageType"]=[[瘀伤#7]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuluoqingyanzhang5]],["lv"]=60,["skillId"]=[[wuluoqingyanzhang]],["tiliCost"]=50,["topLimit"]=6,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[烟雾弥漫]]},["wuluoqingyanzhang6"]={["actionText"]=[[$N双掌齐推，振起一阵劲风，一招「烟消云散」在一丈开外击向$n。]],["atkList"]=[[wuluoqingyanzhang6P1]],["attack"]=12.07,["attackAverage"]=7.22,["damageType"]=[[瘀伤#9]],["hit"]=0.4,["hurtPosClass"]=[[default]],["id"]=[[wuluoqingyanzhang6]],["lv"]=100,["skillId"]=[[wuluoqingyanzhang]],["tiliCost"]=50,["topLimit"]=20,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[烟消云散]]},["wuqichaoyangjian1"]={["actionText"]=[[$N一式HIY「天九成金」NOR，$Nw从上至下猛劈，剑锋直出，挟爆裂之声骤然斩向$n的$l。]],["atkList"]=[[wuqichaoyangjian1P1]],["attack"]=8,["attackAverage"]=9.6,["damageType"]=[[刺伤#1]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian1]],["lv"]=0,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[天九成金]]},["wuqichaoyangjian10"]={["actionText"]=[[$N飞身而起，剑尖颤动，如撒落尘，劲力罩向$n的胸口。]],["atkList"]=[[wuqichaoyangjian10P1]],["attack"]=40.93,["attackAverage"]=28.53,["damageType"]=[[刺伤#7]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian10]],["lv"]=500,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=220,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[土气相汇]]},["wuqichaoyangjian11"]={["actionText"]=[[$N手中$Nw连出五剑，一招HIW「七返九转」NOR，五道剑芒如罡风呼啸，向$n疾刮而去$n在正值惊愕时，又是一剑HIW「复归于数极」NOR直刺而来。]],["atkList"]=[[wuqichaoyangjian11P1]],["attack"]=47.76,["attackAverage"]=31.15,["damageType"]=[[刺伤#7]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian11]],["lv"]=520,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=220,["zhaoId"]=11,["zhaoIdText"]=[[第十一招]],["zhaoName"]=[[七返九转]]},["wuqichaoyangjian2"]={["actionText"]=[[$N运剑斜向猛劈，剑锋颤动，挟裹破空之声斩向$n的要害。]],["atkList"]=[[wuqichaoyangjian2P1]],["attack"]=8.05,["attackAverage"]=9.63,["damageType"]=[[刺伤#2]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian2]],["lv"]=50,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=20,["zhaoId"]=2,["zhaoIdText"]=[[第二招]],["zhaoName"]=[[金气相汇]]},["wuqichaoyangjian3"]={["actionText"]=[[$N运气施出HIG「地八成木」NOR，$Nw剑尖逼出三道青芒，闪电般破空射向$n的$l。]],["atkList"]=[[wuqichaoyangjian3P1]],["attack"]=12.88,["attackAverage"]=11.57,["damageType"]=[[刺伤#3]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian3]],["lv"]=80,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=20,["zhaoId"]=3,["zhaoIdText"]=[[第三招]],["zhaoName"]=[[地八成木]]},["wuqichaoyangjian4"]={["actionText"]=[[$N运剑凭空一指，剑势奇快，一剑挺刺向$n$l。]],["atkList"]=[[wuqichaoyangjian4P1]],["attack"]=12.92,["attackAverage"]=12.56,["damageType"]=[[刺伤#3]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian4]],["lv"]=140,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=30,["zhaoId"]=4,["zhaoIdText"]=[[第四招]],["zhaoName"]=[[木气相汇]]},["wuqichaoyangjian5"]={["actionText"]=[[$N举剑跃出，一式HIC「地六成水」NOR，$Nw幻出万道剑芒，于剑光中疾取$n的$l。]],["atkList"]=[[wuqichaoyangjian5P1]],["attack"]=23.62,["attackAverage"]=15.71,["damageType"]=[[刺伤#4]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian5]],["lv"]=200,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=60,["zhaoId"]=5,["zhaoIdText"]=[[第五招]],["zhaoName"]=[[地六成水]]},["wuqichaoyangjian6"]={["actionText"]=[[$N运转水之内劲，剑势轻灵跳动，剑随身长，右手运剑刺向$n$l。]],["atkList"]=[[wuqichaoyangjian6P1]],["attack"]=23.76,["attackAverage"]=17.85,["damageType"]=[[刺伤#5]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian6]],["lv"]=250,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=80,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[水气相汇]]},["wuqichaoyangjian7"]={["actionText"]=[[$N身法加快，一招HIR「天七成火」NOR，$Nw弯弯递出，$n正惊疑间，剑上突然豪光绽放，道道剑气向$n笼罩而去。]],["atkList"]=[[wuqichaoyangjian7P1]],["attack"]=32.96,["attackAverage"]=20.95,["damageType"]=[[刺伤#5]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian7]],["lv"]=350,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=100,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[天七成火]]},["wuqichaoyangjian8"]={["actionText"]=[[$N飞身而起，自上而下，挟火劲斩向$n的胸口。]],["atkList"]=[[wuqichaoyangjian8P1]],["attack"]=33.92,["attackAverage"]=23.42,["damageType"]=[[刺伤#6]],["hit"]=0.6,["hurtPosClass"]=[[default]],["id"]=[[wuqichaoyangjian8]],["lv"]=400,["skillId"]=[[wuqichaoyangjian]],["tiliCost"]=48,["topLimit"]=200,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[火气相汇]]},["wuqichaoyangjian9"]={["actionText"]=[[$N双腿半屈半蹲，一式YEL「地十成土」NOR，剑尖划出无数圆圈，强光骤起，笼罩天地。]],["atkList"]=[[wuqichaoyangjian9P1]],["attack"]=40.7,["attackAverage"]=26.24,["damageType"]=[[刺伤#6]],["hit"]=0.6,["hurtPosCla