imit"]=80,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[暴风绞沙]]},["xuanyuanfufa7"]={["actionText"]=[[$N跃至半空，使出一招RAN「九霄落雷」NOR，手中$Nw隐挟雷音，迅捷挥出，织成一道斧网向$n罩去。]],["atkList"]=[[xuanyuanfufa7P1]],["attack"]=28.84,["attackAverage"]=16.59,["damageType"]=[[砍伤#5]],["hit"]=0.3,["hurtPosClass"]=[[default]],["id"]=[[xuanyuanfufa7]],["lv"]=160,["skillId"]=[[xuanyuanfufa]],["tiliCost"]=50,["topLimit"]=100,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[九霄落雷]]},["xuanyuanfufa8"]={["actionText"]=[[$N凝气守中，运转$Nw化大巧为大拙，运劲逼出丈许雪亮光芒，一招RAN「疾风骤雨」NOR快攻向$n。]],["atkList"]=[[xuanyuanfufa8P1]],["attack"]=33.15,["attackAverage"]=19.49,["damageType"]=[[砍伤#5]],["hit"]=0.3,["hurtPosClass"]=[[default]],["id"]=[[xuanyuanfufa8]],["lv"]=200,["skillId"]=[[xuanyuanfufa]],["tiliCost"]=50,["topLimit"]=120,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[疾风骤雨]]},["xuanyuanfufa9"]={["actionText"]=[[$N挥斧由中宫直进，招至半途，翻腕转斧，一招RAN「旱地雷音」NOR击出，斧影纷繁，从八个方位劈向$n的$l。]],["atkList"]=[[xuanyuanfufa9P1#xuanyuanfufa9P2]],["attack"]=37.51,["attackAverage"]=22.33,["damageType"]=[[砍伤#6]],["hit"]=0.3,["hurtPosClass"]=[[default]],["id"]=[[xuanyuanfufa9]],["lv"]=240,["skillId"]=[[xuanyuanfufa]],["tiliCost"]=50,["topLimit"]=140,["zhaoId"]=9,["zhaoIdText"]=[[第九招]],["zhaoName"]=[[旱地雷音]]},["xuedaodaofa1"]={["actionText"]=[[$N高举手中$Nw，使出一招RAN「磨牙吮血」NOR，一刀斜劈$n的$l。]],["atkList"]=[[xuedaodaofa1P1]],["attack"]=4.5,["attackAverage"]=5.4,["damageType"]=[[砍伤#1]],["hit"]=0.45,["hurtPosClass"]=[[default]],["id"]=[[xuedaodaofa1]],["lv"]=0,["skillId"]=[[xuedaodaofa]],["tiliCost"]=47,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[磨牙吮血]]},["xuedaodaofa10"]={["actionText"]=[[$N衔$Nw在口，空手在$n身旁穿来插去，蓦地里右手从口中抽出刀来，RAN「血海茫茫」NOR一挥之下，刀锋直劈$n$l。]],["atkList"]=[[xuedaodaofa10P1]],["attack"]=27.57,["attackAverage"]=17.31,["damageType"]=[[砍伤#5]],["hit"]=0.45,["hurtPosClass"]=[[default]],["id"]=[[xuedaodaofa10]],["lv"]=140,["skillId"]=[[xuedaodaofa]],["tiliCost"]=47,["topLimit"]=70,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[血海茫茫]]},["x