]=[[飞龙献爪]]},["yingzhuagong6"]={["actionText"]=[[$N伏地滑行，一式「拨云瞻日」，上手袭向膻中大穴，下手反抓$n的裆部。]],["atkList"]=[[yingzhuagong6P1]],["attack"]=6.01,["attackAverage"]=3.84,["damageType"]=[[内伤#6]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[yingzhuagong6]],["lv"]=60,["skillId"]=[[yingzhuagong]],["tiliCost"]=50,["topLimit"]=5,["zhaoId"]=6,["zhaoIdText"]=[[第六招]],["zhaoName"]=[[拨云瞻日]]},["yingzhuagong7"]={["actionText"]=[[$N左右手掌爪互逆，一式「搏击长空」，无数道劲气破空而出，迅疾无比地击向$n。]],["atkList"]=[[yingzhuagong7P1]],["attack"]=7.23,["attackAverage"]=4.53,["damageType"]=[[内伤#7]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[yingzhuagong7]],["lv"]=80,["skillId"]=[[yingzhuagong]],["tiliCost"]=50,["topLimit"]=15,["zhaoId"]=7,["zhaoIdText"]=[[第七招]],["zhaoName"]=[[搏击长空]]},["yingzhuagong8"]={["actionText"]=[[$N腾空高飞三丈，一式「鹰扬万里」，天空中顿时显出一个巨灵爪影，缓缓罩向$n。]],["atkList"]=[[yingzhuagong8P1]],["attack"]=8.45,["attackAverage"]=5.24,["damageType"]=[[内伤#7]],["hit"]=0.8,["hurtPosClass"]=[[default]],["id"]=[[yingzhuagong8]],["lv"]=100,["skillId"]=[[yingzhuagong]],["tiliCost"]=50,["topLimit"]=20,["zhaoId"]=8,["zhaoIdText"]=[[第八招]],["zhaoName"]=[[鹰扬万里]]},["yinsuojinling1"]={["actionText"]=[[RAN$N劲贯$Nw，突然之间，丝带环绕，像一条银蛇扑向$nNOR。]],["atkList"]=[[yinsuojinling1P1]],["attack"]=0,["attackAverage"]=0,["damageType"]=[[震伤#1]],["hit"]=0.2,["hurtPosClass"]=[[default]],["id"]=[[yinsuojinling1]],["lv"]=0,["skillId"]=[[yinsuojinling]],["tiliCost"]=50,["topLimit"]=0,["zhaoId"]=1,["zhaoIdText"]=[[第一招]],["zhaoName"]=[[霞衣席上]]},["yinsuojinling10"]={["actionText"]=[[RAN$n想要冲到$N面前，$N手中$Nw直点$n胸口檀中穴！$n慌忙招架，不想$N的$Nw突然转向点向$lNOR。]],["atkList"]=[[yinsuojinling10P1]],["attack"]=22.58,["attackAverage"]=11.27,["damageType"]=[[震伤#8]],["hit"]=0.5,["hurtPosClass"]=[[default]],["id"]=[[yinsuojinling10]],["lv"]=120,["skillId"]=[[yinsuojinling]],["tiliCost"]=50,["topLimit"]=12,["zhaoId"]=10,["zhaoIdText"]=[[第十招]],["zhaoName"]=[[翩兰苕翠]]},["yinsuojinling11"]={["actionText"]=[[RAN$N手中$Nw飞舞，$n眼前仿佛突然出现了七八条$Nw一齐点向$nNOR。]],["atkList"]=[[yinsuojinling11P1]],["attack"]=